// Local renderer for the plain Mermaid flowchart subset generated by Walkthrough.
// Pure geometry: shared by native UI and tests, with no network or file writes.
const invalid = () => { throw Object.assign(new Error("Architecture must be a plain Mermaid flowchart with declared nodes and edges."), { code: "invalid" }); };

export function parseMermaid(source) {
  const lines = String(source ?? "").split("\n").map((s) => s.trim()).filter(Boolean);
  const header = /^flowchart (TB|TD|LR)$/.exec(lines.shift() ?? "");
  if (!header) invalid();
  const nodes = [], edges = [], ids = new Set(), groups = [], groupIds = new Set();
  let activeGroup = null;
  for (const line of lines) {
    const node = /^([A-Za-z][A-Za-z0-9_]*)\["([^"<>`\\]+)"\]$/.exec(line);
    const edge = /^([A-Za-z][A-Za-z0-9_]*) -->(?:\|"([^"<>`|\\]+)"\|)? ([A-Za-z][A-Za-z0-9_]*)$/.exec(line);
    const group = /^subgraph ([A-Za-z][A-Za-z0-9_]*)\["([^"<>`|\\]+)"\]$/.exec(line);
    if (group) {
      if (activeGroup || groupIds.has(group[1]) || ids.has(group[1])) invalid();
      activeGroup = { id: group[1], title: group[2], nodes: [] };
      groupIds.add(group[1]); groups.push(activeGroup);
    } else if (line === "end") {
      if (!activeGroup || !activeGroup.nodes.length) invalid();
      activeGroup = null;
    } else if (node) {
      if (ids.has(node[1]) || groupIds.has(node[1])) invalid();
      ids.add(node[1]); nodes.push({ id: node[1], label: node[2] });
      if (activeGroup) activeGroup.nodes.push(node[1]);
    } else if (edge && !activeGroup) edges.push({ from: edge[1], to: edge[3], ...(edge[2] ? { label: edge[2] } : {}) });
    else invalid();
  }
  if (activeGroup || !nodes.length || edges.some((e) => !ids.has(e.from) || !ids.has(e.to))) invalid();
  return { direction: header[1] === "LR" ? "LR" : "TB", nodes, edges, ...(groups.length ? { groups } : {}) };
}

/** Wrap labels without removing text, including long identifiers. */
export function wrapLabel(text, limit = 25) {
  const out = [];
  let line = "";
  for (let word of text.split(/\s+/)) {
    if (line && line.length + word.length + 1 > limit) { out.push(line); line = ""; }
    while (word.length > limit) { out.push(word.slice(0, limit)); word = word.slice(limit); }
    if (word) line += (line ? " " : "") + word;
  }
  if (line) out.push(line);
  return out;
}

/** Condense cycles before assigning ranks, so cyclic diagrams always terminate. */
function ranksFor(graph) {
  const adj = new Map(graph.nodes.map((n) => [n.id, []]));
  for (const e of graph.edges) adj.get(e.from).push(e.to);
  const index = new Map(), low = new Map(), stack = [], active = new Set(), groups = [];
  let next = 0;
  const visit = (id) => {
    index.set(id, next); low.set(id, next++); stack.push(id); active.add(id);
    for (const to of adj.get(id)) {
      if (!index.has(to)) { visit(to); low.set(id, Math.min(low.get(id), low.get(to))); }
      else if (active.has(to)) low.set(id, Math.min(low.get(id), index.get(to)));
    }
    if (low.get(id) === index.get(id)) {
      const group = [];
      let member;
      do { member = stack.pop(); active.delete(member); group.push(member); } while (member !== id);
      groups.push(group);
    }
  };
  for (const n of graph.nodes) if (!index.has(n.id)) visit(n.id);
  const groupOf = new Map();
  groups.forEach((g, i) => g.forEach((id) => groupOf.set(id, i)));
  const incoming = groups.map(() => 0), successors = groups.map(() => new Set());
  for (const e of graph.edges) {
    const a = groupOf.get(e.from), b = groupOf.get(e.to);
    if (a !== b && !successors[a].has(b)) { successors[a].add(b); incoming[b]++; }
  }
  const ranks = groups.map(() => 0), queue = [];
  incoming.forEach((n, i) => { if (!n) queue.push(i); });
  for (let i = 0; i < queue.length; i++) {
    const a = queue[i];
    for (const b of successors[a]) {
      ranks[b] = Math.max(ranks[b], ranks[a] + 1);
      if (--incoming[b] === 0) queue.push(b);
    }
  }
  return new Map(graph.nodes.map((n) => [n.id, ranks[groupOf.get(n.id)]]));
}

/** Layered nodes, orthogonal connectors and explicit arrowheads in logical px. */
export function layoutDiagram(source, connections = [], groups = []) {
  const graph = parseMermaid(source), rankOf = ranksFor(graph);
  graph.edges = graph.edges.map((edge) => {
    const connection = connections.find((c) => c.from === edge.from && c.to === edge.to);
    return connection ? { ...edge, label: connection.label, missing: connection.missing ?? 0 } : edge;
  });
  const labeled = graph.edges.some((e) => e.label);
  const cycleEdges = graph.edges.filter((e) => rankOf.get(e.to) <= rankOf.get(e.from)).length;
  const horizontal = graph.direction === "LR";
  const labels = new Map(graph.nodes.map((n) => [n.id, wrapLabel(n.label)]));
  const nodeW = 224, nodeH = Math.max(96, ...[...labels.values()].map((l) => l.length * 18 + 54));
  const pad = 40, gap = labeled ? Math.max(112, 48 + cycleEdges * 36) : Math.max(88, 48 + graph.edges.length * 8), separation = 48;
  const layers = Array.from({ length: Math.max(...rankOf.values()) + 1 }, () => []);
  for (const n of graph.nodes) layers[rankOf.get(n.id)].push(n);
  const widest = Math.max(...layers.map((l) => l.length));
  const secondarySize = horizontal ? nodeH : nodeW;
  const primarySize = horizontal ? nodeW : nodeH;
  const span = widest * secondarySize + (widest - 1) * separation;
  let nodes = layers.flatMap((layer, rank) => layer.map((n, i) => {
    const secondary = pad + (span - (layer.length * secondarySize + (layer.length - 1) * separation)) / 2 + i * (secondarySize + separation);
    const primary = pad + rank * (primarySize + gap);
    return { ...n, rank, lines: labels.get(n.id), x: horizontal ? primary : secondary, y: horizontal ? secondary : primary, width: nodeW, height: nodeH };
  }));
  const boundaries = groups.length ? groups : graph.groups ?? [];
  const grouped = boundaries.length ? layoutGroupLanes(layers, boundaries, { horizontal, nodeW, nodeH, labels, gap, separation, pad }) : null;
  if (grouped) nodes = grouped.nodes;
  const frames = grouped?.groups ?? [];
  const byId = new Map(nodes.map((n) => [n.id, n]));
  let width = Math.max(...nodes.map((n) => n.x + n.width), ...frames.map((g) => g.x + g.width)) + pad;
  let height = Math.max(...nodes.map((n) => n.y + n.height), ...frames.map((g) => g.y + g.height)) + pad;
  const baseWidth = width, baseHeight = height;
  // Separate ports for fan-in and fan-out, preserving the source edge order.
  const outgoing = new Map(nodes.map((n) => [n.id, graph.edges.filter((e) => e.from === n.id)]));
  const incoming = new Map(nodes.map((n) => [n.id, graph.edges.filter((e) => e.to === n.id)]));
  const port = (node, edge, entering) => {
    const list = (entering ? incoming : outgoing).get(node.id);
    return (list.indexOf(edge) + 1) / (list.length + 1);
  };
  let lane = 0;
  const edges = graph.edges.map((edge) => {
    const a = byId.get(edge.from), b = byId.get(edge.to);
    const out = port(a, edge, false), into = port(b, edge, true);
    const ax = a.x + nodeW * out, bx = b.x + nodeW * into;
    const ay = a.y + nodeH * out, by = b.y + nodeH * into;
    let points;
    if (b.rank === a.rank + 1) {
      if (horizontal) {
        const x = a.x + nodeW + gap / 2;
        points = [[a.x + nodeW, ay], [x, ay], [x, by], [b.x, by]];
      } else {
        const y = a.y + nodeH + gap / 2;
        points = [[ax, a.y + nodeH], [ax, y], [bx, y], [bx, b.y]];
      }
    } else if (b.rank > a.rank + 1) {
      // Skipped ranks use an outer lane rather than passing through other nodes.
      const offset = 16 + lane++ * (labeled ? 36 : 12);
      if (horizontal) {
        const y = baseHeight + offset;
        points = [[a.x + nodeW, ay], [a.x + nodeW + 18, ay], [a.x + nodeW + 18, y], [b.x - 18, y], [b.x - 18, by], [b.x, by]];
        height = Math.max(height, y + pad);
      } else {
        const x = baseWidth + offset;
        points = [[ax, a.y + nodeH], [ax, a.y + nodeH + 18], [x, a.y + nodeH + 18], [x, b.y - 18], [bx, b.y - 18], [bx, b.y]];
        width = Math.max(width, x + pad);
      }
    } else {
      // Edges within a cycle (including self-loops) use a gap beside the layer.
      if (horizontal) {
        const x = a.x + nodeW + 24 + lane++ * (labeled ? 36 : 8);
        points = [[a.x + nodeW, a.y + nodeH / 3], [x, a.y + nodeH / 3], [x, b.y + 2 * nodeH / 3], [b.x + nodeW, b.y + 2 * nodeH / 3]];
        width = Math.max(width, x + pad);
      } else {
        const y = a.y + nodeH + 24 + lane++ * (labeled ? 36 : 8);
        points = [[a.x + nodeW / 3, a.y + nodeH], [a.x + nodeW / 3, y], [b.x + 2 * nodeW / 3, y], [b.x + 2 * nodeW / 3, b.y + nodeH]];
        height = Math.max(height, y + pad);
      }
    }
    // Remove duplicate bends to keep the last segment's direction well-defined.
    points = points.filter((p, i) => !i || p[0] !== points[i - 1][0] || p[1] !== points[i - 1][1]);
    const end = points.at(-1), before = points.at(-2);
    const dx = end[0] - before[0], dy = end[1] - before[1], length = Math.hypot(dx, dy);
    const ux = dx / length, uy = dy / length, size = 8;
    const arrow = [end, [end[0] - size * ux + size * 0.5 * uy, end[1] - size * uy - size * 0.5 * ux], [end[0] - size * ux - size * 0.5 * uy, end[1] - size * uy + size * 0.5 * ux]];
    return { ...edge, points, arrow };
  });
  return placeConnectionLabels({ direction: graph.direction, nodes, edges, groups: frames, width, height });
}

/** Portable Mermaid export with exactly the same labels as the native view. */
export function mermaidWithConnections(source, connections = [], groups = []) {
  if (!connections.length && !groups.length) return source;
  const graph = parseMermaid(source);
  const boundaries = groups.length ? groups : graph.groups ?? [];
  const assigned = new Set(boundaries.flatMap((g) => g.nodes));
  const declaration = (node) => `${node.id}["${node.label}"]`;
  const blocks = boundaries.flatMap((g) => [`subgraph ${g.id}["${g.title}"]`,
    ...graph.nodes.filter((n) => g.nodes.includes(n.id)).map(declaration), "end"]);
  return [`flowchart ${graph.direction}`, ...blocks, ...graph.nodes.filter((n) => !assigned.has(n.id)).map(declaration), ...graph.edges.map((e) => {
    const label = connections.find((c) => c.from === e.from && c.to === e.to)?.label ?? e.label;
    return `${e.from} -->${label ? `|"${label}"|` : ""} ${e.to}`;
  })].join("\n");
}

const intersects = (a, b, pad = 0) => a.x < b.x + b.width + pad && a.x + a.width + pad > b.x && a.y < b.y + b.height + pad && a.y + a.height + pad > b.y;

/** Place small callouts near their own connector, avoiding cards, other labels
 * and unrelated wires. Dense diagrams use a reserved outer callout gutter. */
function placeConnectionLabels(graph) {
  const boxes = [], originalWidth = graph.width;
  for (const [index, edge] of graph.edges.entries()) {
    if (!edge.label) continue;
    let lines = wrapLabel(edge.label, 24);
    let width = Math.max(60, ...lines.map((s) => s.length * 6 + 16)), height = lines.length * 14 + 10;
    const segments = edge.points.slice(1).map((b, i) => ({ a: edge.points[i], b }));
    const candidates = [];
    for (const { a, b } of segments) {
      for (const fraction of [0.5, 0.3, 0.7, 0.15, 0.85]) {
        const anchor = [a[0] + (b[0] - a[0]) * fraction, a[1] + (b[1] - a[1]) * fraction];
        const length = Math.abs(b[0] - a[0]) + Math.abs(b[1] - a[1]);
        if (length >= (a[1] === b[1] ? width : height) + 12) {
          candidates.push({ x: anchor[0] - width / 2, y: anchor[1] - height / 2, anchor });
        }
        if (a[1] === b[1]) {
          candidates.push({ x: anchor[0] - width / 2, y: anchor[1] - height - 5, anchor });
          candidates.push({ x: anchor[0] - width / 2, y: anchor[1] + 5, anchor });
        } else {
          candidates.push({ x: anchor[0] + 6, y: anchor[1] - height / 2, anchor });
          candidates.push({ x: anchor[0] - width - 6, y: anchor[1] - height / 2, anchor });
        }
      }
    }
    const otherWires = graph.edges.filter((e) => e !== edge).flatMap((e) => e.points.slice(1).map((b, i) => {
      const a = e.points[i];
      return { x: Math.min(a[0], b[0]), y: Math.min(a[1], b[1]), width: Math.max(1, Math.abs(a[0] - b[0])), height: Math.max(1, Math.abs(a[1] - b[1])) };
    }));
    const fits = (p) => {
      const box = { ...p, width, height };
      return p.x >= 8 && p.y >= 8 && p.x + width <= originalWidth - 8 && p.y + height <= graph.height - 8
        && !graph.nodes.some((n) => intersects(box, n, 8))
        && !(graph.groups ?? []).some((g) => intersects(box, { ...g, height: 36 }, 3)) && !boxes.some((b) => intersects(box, b, 5)) && !otherWires.some((w) => intersects(box, w, 3));
    };
    let position = candidates.find(fits);
    if (!position) {
      // Numbered gutter callouts avoid drawing a new leader across cards.
      lines = wrapLabel(`${index + 1}. ${edge.label}`, 24);
      width = Math.max(60, ...lines.map((s) => s.length * 6 + 16));
      height = lines.length * 14 + 10;
      const anchor = edge.points[Math.floor(edge.points.length / 2)];
      position = { x: originalWidth + 16, y: Math.max(12, anchor[1] - height / 2), anchor, detached: true, number: index + 1 };
      while (boxes.some((box) => intersects({ ...position, width, height }, box, 6))) position.y += height + 8;
    }
    edge.labelBox = { ...position, width, height, lines };
    boxes.push(edge.labelBox);
    graph.width = Math.max(graph.width, position.x + width + 24);
    graph.height = Math.max(graph.height, position.y + height + 24);
  }
  return graph;
}

/** Each evidenced boundary gets a separate lane; unassigned components retain
 * a lane without a frame. Global graph ranks preserve all cross-group flows. */
function layoutGroupLanes(layers, boundaries, { horizontal, nodeW, nodeH, labels, gap, separation, pad }) {
  const declared = new Set(layers.flatMap((layer) => layer.map((n) => n.id))), assigned = new Set();
  for (const group of boundaries) for (const id of group.nodes) {
    if (!declared.has(id) || assigned.has(id)) invalid();
    assigned.add(id);
  }
  const unassigned = [...declared].filter((id) => !assigned.has(id));
  const lanes = [...boundaries, ...(unassigned.length ? [{ id: null, nodes: unassigned }] : [])];
  const secondarySize = horizontal ? nodeH : nodeW, primarySize = horizontal ? nodeW : nodeH;
  const primarySpan = layers.length * primarySize + (layers.length - 1) * gap;
  const nodes = [], groups = [];
  let cursor = pad;
  for (const lane of lanes) {
    const members = new Set(lane.nodes);
    const rows = layers.map((layer) => layer.filter((n) => members.has(n.id)));
    const widest = Math.max(...rows.map((r) => r.length));
    if (!widest) invalid();
    const contentSize = widest * secondarySize + (widest - 1) * separation;
    const laneSize = contentSize + (horizontal ? 64 : 48);
    rows.forEach((row, rank) => row.forEach((n, i) => {
      const span = row.length * secondarySize + (row.length - 1) * separation;
      const secondary = cursor + (horizontal ? 40 : 24) + (contentSize - span) / 2 + i * (secondarySize + separation);
      const primary = pad + (horizontal ? 24 : 40) + rank * (primarySize + gap);
      nodes.push({ ...n, rank, lines: labels.get(n.id), x: horizontal ? primary : secondary, y: horizontal ? secondary : primary, width: nodeW, height: nodeH });
    }));
    if (lane.id) groups.push({ ...lane, titleLines: wrapLabel(lane.title, 24),
      x: horizontal ? pad : cursor, y: horizontal ? cursor : pad,
      width: horizontal ? primarySpan + 48 : laneSize, height: horizontal ? laneSize : primarySpan + 64 });
    cursor += laneSize + 24;
  }
  return { nodes, groups };
}
